#!/usr/bin/env python3
"""Write packaging/flatpak/requirements.txt from uv.lock.

The Flatpak installs exactly what uv.lock pins, by hash, into the Python it bundles:
`uv export` for the runtime dependencies, plus setuptools, which builds the package
itself there. Re-run after `uv lock`; tests/test_flatpak.py fails while they differ.

    uv run scripts/flatpak_requirements.py
"""

import subprocess
import sys
import tomllib
from pathlib import Path

ROOT = Path(__file__).resolve().parent.parent
OUT = ROOT / "packaging/flatpak/requirements.txt"
HEADER = (
    "# Generated by scripts/flatpak_requirements.py from uv.lock. Do not edit:\n"
    "# re-run it after `uv lock`.\n"
)


def build_backend() -> str:
    lock = tomllib.loads((ROOT / "uv.lock").read_text(encoding="utf-8"))
    [setuptools] = [p for p in lock["package"] if p["name"] == "setuptools"]
    [wheel] = setuptools["wheels"]
    return f"setuptools=={setuptools['version']} \\\n    --hash={wheel['hash']}\n"


def runtime() -> str:
    done = subprocess.run(
        [
            "uv",
            "export",
            "--frozen",
            "--no-dev",
            "--no-emit-project",
            "--no-header",
            "--no-annotate",
            "--format",
            "requirements-txt",
        ],
        cwd=ROOT,
        check=True,
        capture_output=True,
        text=True,
    )
    return done.stdout


def main() -> int:
    text = HEADER + runtime() + build_backend()
    if "--check" in sys.argv[1:]:
        if OUT.read_text(encoding="utf-8") != text:
            print(f"{OUT} is stale; run scripts/flatpak_requirements.py", file=sys.stderr)
            return 1
        return 0
    OUT.write_text(text, encoding="utf-8")
    print(f"wrote {OUT}")
    return 0


if __name__ == "__main__":
    sys.exit(main())
